/**
 * The home screen of the web shell.
 *
 * Its state and the changes it makes are [ge.dakalebi.presentation.DashboardViewModel]'s.
 * The catalog and the progress it draws come from the catalog store, which every
 * screen reads. Whether the menu is open is the one thing kept here, because
 * nothing else cares.
 */
@Composable
fun DashboardScreen() {
    val session = session()
    val sessionState = sessionState()
    val catalog = catalog()
    val dashboard = rememberDashboardViewModel()
    val ui by dashboard.state.collectAsState()

    var menuOpen by remember { mutableStateOf(false) }

    val season = dashboard.season(ui)
    val episodes = season?.let { catalog.season(it) } ?: emptyList()
    val inProgress = catalog.inProgress(limit = 12)

    Div {
        DashboardNav(onMenu = { menuOpen = true })

        when {
            catalog.loading -> LoadingRails()

            catalog.loadError != null -> LoadFailed(
                message = ErrorMessages.catalogLoad(catalog.loadError),
                onRetry = session::retryCatalogLoad,
            )

            catalog.episodes.isEmpty() -> EmptyCatalog(
                canRefresh = sessionState.isAdmin,
                refreshing = catalog.refreshing,
                note = catalog.refreshNote,
                onRefresh = dashboard::refreshCatalog,
            )

            else -> {
                catalog.continueWatching?.let { Hero(it) }

                Div({ classes("rails") }) {
                    if (inProgress.isNotEmpty()) {
                        Rail(
                            title = S.continueLabel.caps,
                            subtitle = "${inProgress.size}",
                            episodes = inProgress,
                            progress = catalog.progress,
                        )
                    }

                    Div {
                        Div({ classes("rail-head") }) {
                            H2 { Text(S.seasons.caps) }
                            Span({ classes("count") }) { Text("${catalog.seasons.size}") }
                        }
                        // A radio group now, not a row of buttons. That is the part
                        // worth noticing: eighteen buttons were eighteen tab stops
                        // with no arrow-key movement between them, and nothing said
                        // which of how many was chosen. Native radios sharing a name
                        // give all of that away for free.
                        SegmentedControl(
                            segments = catalog.seasons.map { number ->
                                val all = catalog.season(number)
                                Segment(
                                    value = number,
                                    label = S.season(number).caps,
                                    complete = all.isNotEmpty() &&
                                        all.all { catalog.progress[it.id]?.isWatched == true },
                                )
                            },
                            selected = season,
                            // Typed after `selected`, which is null before the catalog arrives.
                            onSelect = { picked -> picked?.let(dashboard::pickSeason) },
                            ariaLabel = S.seasons,
                            style = SegmentedStyle.Rail,
                            // Only the page gutter is left: the rail's own scrolling,
                            // gap and hidden scrollbar are keel's.
                            attrs = { classes("chips") },
                        )
                    }

                    Div {
                        Div({ classes("rail-head") }) {
                            H2 { Text((season?.let { S.season(it) } ?: S.episodes).caps) }
                            Span({ classes("count") }) {
                                val done = episodes.count { catalog.progress[it.id]?.isWatched == true }
                                Text(S.episodeCount(episodes.size, done).caps)
                            }
                            Div({ classes("spacer") })
                            SeasonMenu(
                                disabled = ui.busy || season == null,
                                onMark = { season?.let { dashboard.ask(DashboardConfirm.MarkSeason(it)) } },
                                onReset = { season?.let { dashboard.ask(DashboardConfirm.ResetSeason(it)) } },
                            )
                        }
                        Div({ classes("grid") }) {
                            episodes.forEach { episode ->
                                EpisodeTile(episode, catalog.progress[episode.id])
                            }
                        }
                    }
                }
            }
        }
    }

    if (menuOpen) {
        MenuSheet(
            onClose = { menuOpen = false },
            onResetAll = {
                menuOpen = false
                dashboard.ask(DashboardConfirm.ResetAll)
            },
            onRefresh = dashboard::refreshCatalog,
            onSignOut = dashboard::signOut,
            onSignIn = {
                menuOpen = false
                session.leaveGuestMode()
            },
            onSwitchToGuest = {
                menuOpen = false
                dashboard.switchToGuest()
            },
            busy = ui.busy,
        )
    }

    when (val confirm = ui.confirm) {
        DashboardConfirm.ResetAll -> ConfirmDialog(
            title = S.resetAllTitle,
            body = S.resetAllBody,
            confirmLabel = S.resetAllConfirm.caps,
            destructive = true,
            onConfirm = dashboard::confirm,
            onDismiss = dashboard::dismiss,
        )

        is DashboardConfirm.MarkSeason -> ConfirmDialog(
            title = S.markSeasonTitle,
            body = S.markSeasonBody("${confirm.season}"),
            confirmLabel = S.markSeasonConfirm.caps,
            onConfirm = dashboard::confirm,
            onDismiss = dashboard::dismiss,
        )

        is DashboardConfirm.ResetSeason -> ConfirmDialog(
            title = S.resetSeasonTitle,
            body = S.resetSeasonBody("${confirm.season}"),
            confirmLabel = S.delete.caps,
            destructive = true,
            onConfirm = dashboard::confirm,
            onDismiss = dashboard::dismiss,
        )

        null -> Unit
    }
}

@Composable
private fun DashboardNav(onMenu: () -> Unit) {
    val session = session()
    val sessionState = sessionState()
    val catalog = catalog()

    Div({ classes("nav") }) {
        IconButton(ariaLabel = S.menu, onClick = onMenu) { Icon(LucideIcon.Menu, size = ICON_NAV) }
        // The mark is lettering, so it *is* the wordmark — the name lives in
        // `alt` rather than being repeated beside it.
        Img(src = "${assetBase}logo.png", alt = S.appName) { classes("nav-mark") }
        Div({ classes("nav-right") }) {
            if (catalog.refreshing) {
                Span({
                    classes("count")
                    style { property("font-size", "11px"); property("color", "var(--mut)") }
                }) {
                    Text(catalog.refreshNote ?: S.refreshing)
                }
            }
            if (sessionState.isGuest) {
                // A guest has no initial to show, and the one thing worth offering
                // them up here is the way to an account.
                Badge(label = S.guest.caps)
                Button(
                    label = S.signIn.caps,
                    onClick = { session.leaveGuestMode() },
                    variant = ButtonVariant.Outline,
                    size = ButtonSize.Small,
                )
            } else {
                Div({ classes("avatar"); attr("title", sessionState.email ?: "") }) {
                    Text(sessionState.email?.take(1)?.uppercase() ?: "?")
                }
            }
        }
    }
}

@Composable
private fun Hero(episode: Episode) {
    val catalog = catalog()
    val entry = catalog.progress[episode.id]
    val watched = entry?.isWatched == true
    val position = entry?.progressSeconds ?: 0
    val duration = entry?.durationSeconds ?: episode.durationSeconds
    val percent = entry?.percent ?: 0.0
    val resuming = !watched && position > 5

    Div({ classes("hero") }) {
        Div({ classes("hero-img") }) { Thumb(episode) }
        Div({ classes("hero-scrim") })
        Div({ classes("hero-body") }) {
            Div({ classes("eyebrow") }) {
                Text(
                    when {
                        resuming -> S.continueLabel
                        watched -> S.lastWatched
                        else -> S.beginning
                    }.caps,
                )
            }
            H1({ classes("hero-h") }) {
                Text(S.season(episode.seasonNumber).caps)
                Div { Text(S.episode(episode.episodeNumber).caps) }
            }
            if (percent > 0) {
                // `onMedia`: the hero bar lies over the episode still, so the track
                // reads `--primary-foreground` at low alpha rather than a page colour
                // that says nothing about what is behind it.
                ProgressBar(
                    fraction = percent / 100.0,
                    ariaLabel = S.statProgress,
                    size = ProgressBarSize.Large,
                    onMedia = true,
                    attrs = { classes("hero-bar") },
                )
            }
            Div({ classes("hero-sub") }) {
                Text(
                    when {
                        watched -> S.watchedLabel
                        duration != null && duration > 0 && position > 0 -> {
                            val left = ((duration - position) / 60.0).roundToInt()
                            S.minutesLeft(
                                left,
                                formatTime(position.toDouble()),
                                formatTime(duration.toDouble()),
                            )
                        }

                        else -> episode.title ?: S.episode(episode.episodeNumber)
                    },
                )
            }
            Div({ classes("hero-cta") }) {
                LinkButton(
                    href = Router.href(Route.Watch(episode.id)),
                    label = "▶  " + (if (resuming) S.resume else S.watch).caps,
                )
                if (!episode.hasVideo) {
                    Span({ classes("hero-sub") }) { Text(S.videoUnavailableForEpisode) }
                }
            }
        }
    }
}

@Composable
private fun SeasonMenu(disabled: Boolean, onMark: () -> Unit, onReset: () -> Unit) {
    var open by remember { mutableStateOf(false) }
    // The wrapper exists only to be what the menu positions against, which is what
    // keel's anchor class says out loud - the old `.rel` was a `position: relative`
    // with no name for why.
    Div({ classNames(dropdownAnchorClasses()) }) {
        IconButton(
            ariaLabel = S.seasonActions,
            onClick = { open = !open },
            enabled = !disabled,
        ) { Icon(LucideIcon.EllipsisVertical, size = ICON_NAV) }

        if (open) {
            // Escape closes it now; before, only a click outside did. The
            // click-catcher and its z-index one below the menu are keel's too - this
            // screen had already had to work out that a scrim could not be one.
            DropdownMenu(onDismiss = { open = false }, ariaLabel = S.seasonActions) {
                DropdownMenuItem(
                    label = S.markSeasonWatched.caps,
                    onClick = { open = false; onMark() },
                )
                DropdownMenuItem(
                    label = S.resetSeasonProgress.caps,
                    onClick = { open = false; onReset() },
                    tone = DropdownItemTone.Danger,
                )
            }
        }
    }
}

/** The global default in web.css's `.ic svg`; neither icon-btn here overrides it. */
private const val ICON_NAV = 20
